                    state['pending'].append(b)
                    i += 1
                    if len(state['pending']) == state['need']:
                        out.append(chr(int.from_bytes(state['pending'], 'big')))
                        state['pending'] = None
                        state['need'] = 0
                    continue
                state['pending'] = None
                state['need'] = 0
                raise ValueError
            if b < 128:
                out.append(chr(b))
                i += 1
            elif 192 <= b <= 223:
                state['pending'] = [b]
                state['need'] = 2
                i += 1
            elif 224 <= b <= 239:
                state['pending'] = [b]
                state['need'] = 3
                i += 1
            elif 240 <= b <= 247:
                state['pending'] = [b]
                state['need'] = 4
                i += 1
            else:
                raise ValueError
        if final:
            if state['pending']:
                state['pending'] = None
                state['need'] = 0
                raise ValueError
        return ''.join(out)

    events = context['events']
    state = {'pending': None, 'need': 0}
    count = 0
    status = 'open'
    for ev in events:
        op = ev['op']
